def units():
    o='';rows=[('бит — 1',1,'bx'),('тетрада — 4',4,'bx'),('байт — 8',8,'bxa'),('сөз — 16*',16,'bx'),('қос сөз — 32*',32,'bx')]
    for j,(lab,n,c) in enumerate(rows):
        y=8+j*26;x0=330-n*7
        o+=TR(100,y+12,lab,'t-s'+(' t-b' if n==8 else ''))+R(x0,y,n*7,16,c,2)
        for k in range(1,n):o+=L(x0+k*7,y+3,x0+k*7,y+13)
    o+=T(170,150,'* x86 мен ПЛК атауы; ARM-да word = 32 бит','t-s mu')+T(170,170,'n бит → 2ⁿ комбинация: 2, 16, 256, 65 536…','t-s')
    return o
