def wheel():
    cx,cy=170,118;o=C(cx,cy,78,'bx')
    for k in range(16):
        v=k if k<8 else k-16;a=math.radians(-90+k*22.5)
        o+=C(round(cx+78*math.cos(a),1),round(cy+78*math.sin(a),1),3,'ac' if k in (7,8) else 'bx')
        o+=T(round(cx+60*math.cos(a),1),round(cy+60*math.sin(a)+4,1),(f'+{v}' if v>0 else str(v)).replace('-','−'),'t-s'+(' t-b' if k in (7,8) else ''))
        o+=T(round(cx+99*math.cos(a),1),round(cy+99*math.sin(a)+4,1),format(k,'04b'),'t-s mu')
    a=math.radians(-90+7.5*22.5);o+=L(round(cx+66*math.cos(a),1),round(cy+66*math.sin(a),1),round(cx+90*math.cos(a),1),round(cy+90*math.sin(a),1),'lna')
    return o+T(cx,cy-2,'4 бит','t-b')+T(cx,cy+16,'қосымша код','t-s')
