    for i,b in enumerate(bits):
        x=18+i*9.5;o+=f'<rect x="{x}" y="40" width="9.5" height="22" class="{"bxa" if i==0 else ("soft" if i<9 else "bx")}"/>'+T(round(x+4.75,2),55,b,'t-s')
    o+=T(22.75,32,'S','t-s t-b')+L(103.5,34,103.5,68,'lna')+T(65.5,80,'дәреже E','t-s')+T(65.5,94,'8 бит','t-s mu')+T(212,80,'мантисса M','t-s')+T(212,94,'23 бит','t-s mu')
