def seg(x,y,on,w=40,h=72):
    s={'a':(x+6,y,w-12,6),'b':(x+w-6,y+6,6,h/2-9),'c':(x+w-6,y+h/2+3,6,h/2-9),'d':(x+6,y+h-6,w-12,6),'e':(x,y+h/2+3,6,h/2-9),'f':(x,y+6,6,h/2-9),'g':(x+6,y+h/2-3,w-12,6)}
    return ''.join((R(*v,'ac',2) if k in on else R(*v,'soft',2)) for k,v in s.items())
