def ascii_fig():
    o='';ch=['P','U','M','P','_','0','1','\\0']
    for i,c in enumerate(ch):
        x=10+i*40;code=0 if c=='\\0' else ord(c)
        o+=T(x+19,22,'n' if i==0 else f'n+{i}','t-s mu')+R(x,30,38,34,'bxa' if i==7 else 'bx',3)+T(x+19,52,c,'t-b')+T(x+19,82,f'0x{code:02X}','t-s')+T(x+19,100,str(code),'t-s mu')
    return o+T(170,126,'7 символ + нөл-терминатор = 8 байт','t-s')
