def pack(lid,order,title,parts,cards,fn):
    d={"format":"besminut-pack","version":1,"course":course,"lectures":[{"id":lid,"order":order,"title":title,"source":"material","parts":parts,"cards":[{"f":f,"b":b} for f,b in cards]}]}
    json.dump(d,open(f'{OUT}/{fn}','w',encoding='utf-8'),ensure_ascii=False)
    print(fn,len(parts),'parts',len(cards),'cards',os.path.getsize(f'{OUT}/{fn}')//1024,'KB')
pack('microprocessors-03-data-types',3,'3-сабақ. Деректер типтері мен форматтары',L3,cards3,'03-data-types.json')
g=json.load(open(f'{OUT}/glossary.json',encoding='utf-8'));have={x['kk'] for x in g}
abbrs={x['abbr'] for x in g if x['abbr']}
for a,b,c,d in new_gloss:
    if a not in have:
        assert not d or d not in abbrs,d
        g.append({"kk":a,"ru":b,"en":c,"abbr":d})
json.dump(g,open(f'{OUT}/glossary.json','w',encoding='utf-8'),ensure_ascii=False,indent=1)
print('glossary',len(g))
